from typing import List

def solution(matrix: List[List[int]]) -> List[int]:
    n = len(matrix)
    keyed = []
    for start in range(n):
        r, dr, s = start, (1 if start < n - 1 else -1), 0
        for c in range(n):
            s += matrix[r][c]
            if n == 1:
                break
            if r == 0:
                dr = 1
            elif r == n - 1:
                dr = -1
            r += dr
        keyed.append((s, matrix[start][0]))
    return [v for _, v in sorted(keyed)]
